// Fractionally tuned Karplus-Strong string. RAM holds evolving string state,
// never a recorded note. Pick-position comb excitation is generated by LFSRs.
module plucked_guitar(
    input wire clk,reset_n,frame_tick,enable,octave,
    input wire [31:0] gate,
    output reg signed [15:0] sample,
    output reg ready
);
    `include "natural_pitch.vh"
    reg signed [17:0] memory[0:8191];
    reg [12:0] address,write_address;
    reg signed [17:0] q,write_data;
    reg write_enable;
    always @(posedge clk) begin
        q<=memory[address];
        if(write_enable) memory[write_address]<=write_data;
    end
    reg [3:0] state;
    reg [4:0] voice;
    reg [31:0] gates,previous_gate;
    reg octave_frame,previous_octave;
    reg [7:0] pointers[0:31];
    reg [15:0] ages[0:31];
    reg signed [17:0] previous[0:31];
    reg [22:0] noise[0:31],lagged_noise[0:31];
    reg [23:0] envelopes[0:31];
    reg [7:0] pointer;
    reg [15:0] age;
    reg [27:0] tuning;
    reg [31:0] slopes,triangle_product;
    reg pick_rising;
    reg [22:0] current_noise,delayed_noise,seed;
    reg [23:0] envelope;
    reg signed [17:0] previous_tap,tap0,tap1,interpolated,filtered;
    reg signed [18:0] difference;
    reg signed [31:0] fractional_product;
    reg signed [20:0] loop_value;
    reg signed [45:0] output_product;
    reg signed [25:0] mix;
    wire [7:0] read0=pointer-tuning[27:20];
    wire [7:0] read1=read0-1'b1;
    wire current_active=age<{8'd0,tuning[27:20]};
    wire delayed_active=age>={8'd0,tuning[7:0]} && age<({8'd0,tuning[27:20]}+{8'd0,tuning[7:0]});
    wire signed [18:0] excitation_raw=
        (current_active ? $signed({{3{current_noise[22]}},current_noise[22:7]}) : 19'sd0)-
        (delayed_active ? $signed({{3{delayed_noise[22]}},delayed_noise[22:7]}) : 19'sd0);
    wire [8:0] position_sum={1'b0,age[7:0]}+{2'b00,tuning[7:1]};
    wire [7:0] pluck_position=position_sum>={1'b0,tuning[27:20]} ? position_sum-tuning[27:20] : position_sum[7:0];
    wire signed [32:0] triangle=current_active ?
        (pick_rising ? -33'sd16384+$signed({1'b0,triangle_product}) : 33'sd16384-$signed({1'b0,triangle_product})) : 33'sd0;
    wire signed [18:0] excitation=(excitation_raw>>>4)+triangle;
    function signed [17:0] clamp18;
        input signed [20:0] v;
        begin clamp18=v>21'sd131071 ? 18'sh1ffff : v< -21'sd131072 ? 18'sh20000 : v[17:0];end
    endfunction
    wire signed [18:0] filter_sum=$signed({interpolated[17],interpolated})+$signed({previous_tap[17],previous_tap});
    wire signed [18:0] half_sum=(filter_sum+(filter_sum<0 ? 19'sd1 : 19'sd0))>>>1;
    wire signed [18:0] extended_filtered={filtered[17],filtered};
    wire signed [18:0] loss=filtered<0 ? -(((-extended_filtered)+19'sd127)>>>7) : (extended_filtered+19'sd127)>>>7;
    integer i;
    always @(posedge clk) begin
        write_enable<=0;
        if(!reset_n || !enable) begin
            state<=0;voice<=0;gates<=0;previous_gate<=0;octave_frame<=0;previous_octave<=0;
            ready<=0;sample<=0;address<=0;write_address<=0;write_data<=0;write_enable<=0;
            pointer<=0;age<=0;tuning<=0;slopes<=0;triangle_product<=0;pick_rising<=0;
            current_noise<=1;delayed_noise<=1;seed<=23'h38b569;
            envelope<=0;previous_tap<=0;tap0<=0;tap1<=0;interpolated<=0;filtered<=0;
            difference<=0;fractional_product<=0;loop_value<=0;output_product<=0;mix<=0;
            for(i=0;i<32;i=i+1) begin
                pointers[i]<=0;ages[i]<=0;previous[i]<=0;noise[i]<=23'h38b569;
                lagged_noise[i]<=23'h38b569;envelopes[i]<=0;
            end
        end else if(frame_tick) begin
            state<=1;voice<=0;gates<=gate;octave_frame<=octave;ready<=0;mix<=0;
        end else case(state)
            1:begin
                tuning<=string_delay({1'b0,voice}+(octave_frame ? 6'd12 : 6'd0));
                slopes<=pick_slopes({1'b0,voice}+(octave_frame ? 6'd12 : 6'd0));
                if(gates[voice] && (!previous_gate[voice] || previous_octave!=octave_frame)) begin
                    pointer<=0;age<=0;previous_tap<=0;envelope<=24'h7fff00;
                    current_noise<=seed;delayed_noise<=seed;
                end else begin
                    pointer<=pointers[voice];age<=ages[voice];previous_tap<=previous[voice];
                    current_noise<=noise[voice];delayed_noise<=lagged_noise[voice];
                    envelope<=gates[voice] ? envelopes[voice] :
                        envelopes[voice]<24'd512 ? 24'd0 : envelopes[voice]-(envelopes[voice]>>9)-1'b1;
                end
                seed<={seed[21:0],seed[22]^seed[17]};state<=2;
            end
            2:begin address<={voice,read0};state<=3;end
            3:state<=4;
            4:begin tap0<=age>={8'd0,tuning[27:20]} ? q : 18'sd0;address<={voice,read1};state<=5;end
            5:state<=6;
            6:begin
                tap1<=age>{8'd0,tuning[27:20]} ? q : 18'sd0;
                pick_rising<=pluck_position<tuning[7:0];
                triangle_product<=pluck_position<tuning[7:0] ? pluck_position*slopes[31:16] :
                    (pluck_position-tuning[7:0])*slopes[15:0];
                state<=7;
            end
            7:begin difference<=$signed({tap1[17],tap1})-$signed({tap0[17],tap0});state<=8;end
            8:begin fractional_product<=difference*$signed({1'b0,tuning[19:8]});state<=9;end
            9:begin interpolated<=tap0+((fractional_product+(fractional_product<0 ? 32'sd4095 : 32'sd0))>>>12);state<=10;end
            10:begin filtered<=half_sum[17:0];state<=11;end
            11:begin loop_value<=$signed({{3{filtered[17]}},filtered})-$signed({{2{loss[18]}},loss})+excitation;state<=12;end
            12:begin
                write_enable<=1;write_address<={voice,pointer};write_data<=clamp18(loop_value);
                output_product<=clamp18(loop_value)*$signed({1'b0,envelope});
                previous[voice]<=interpolated;pointers[voice]<=pointer+1'b1;
                ages[voice]<=age==65535 ? age : age+1'b1;envelopes[voice]<=envelope;
                noise[voice]<=current_active ? {current_noise[21:0],current_noise[22]^current_noise[17]} : current_noise;
                lagged_noise[voice]<=delayed_active ? {delayed_noise[21:0],delayed_noise[22]^delayed_noise[17]} : delayed_noise;
                state<=13;
            end
            13:begin
                mix<=mix+(output_product>>>27);
                if(voice==31) state<=14;else begin voice<=voice+1'b1;state<=1;end
            end
            14:begin
                sample<=mix>26'sd32767 ? 16'sh7fff : mix< -26'sd32768 ? 16'sh8000 : mix[15:0];
                ready<=1;previous_gate<=gates;previous_octave<=octave_frame;state<=0;
            end
            default:state<=0;
        endcase
    end
endmodule

// Four analytic guitar-body band-pass modes plus DC blocking, Q16.8 state.
module guitar_body(
    input wire clk,reset_n,sample_valid,enable,
    input wire signed [15:0] sample_in,
    output reg signed [15:0] sample_out,
    output reg valid
);
    `include "body_coefficients.vh"
    reg [2:0] state;
    reg [1:0] mode;
    reg signed [23:0] y1[0:3],y2[0:3];
    reg signed [23:0] x1,x2,x,dc_input,dc_state;
    reg signed [27:0] total,mode_value;
    reg signed [54:0] product_a,product_b,product_c;
    reg signed [15:0] dry;
    reg [12:0] quiet_frames;
    wire signed [24:0] dc_extended={dc_state[23],dc_state};
    wire signed [24:0] dc_loss=dc_state<0 ? -(((-dc_extended)+25'sd1023)>>>10) : (dc_extended+25'sd1023)>>>10;
    wire signed [24:0] delta=$signed({x[23],x})-$signed({x2[23],x2});
    wire signed [55:0] sum=$signed({product_a[54],product_a})+$signed({product_b[54],product_b})+$signed({product_c[54],product_c});
    wire signed [27:0] rounded=(sum+(sum<0 ? 56'sd268435455 : 56'sd0))>>>28;
    wire signed [27:0] wet=total>>>1;
    wire signed [27:0] combined=$signed({{4{dc_state[23]}},dc_state})+wet;
    wire signed [27:0] pcm=(combined+(combined<0 ? 28'sd255 : 28'sd0))>>>8;
    integer i;
    always @(posedge clk) begin
        valid<=0;
        if(!reset_n || !enable) begin
            state<=0;mode<=0;x1<=0;x2<=0;x<=0;dc_input<=0;dc_state<=0;total<=0;mode_value<=0;
            product_a<=0;product_b<=0;product_c<=0;dry<=0;sample_out<=0;valid<=0;quiet_frames<=0;
            for(i=0;i<4;i=i+1) begin y1[i]<=0;y2[i]<=0;end
        end else case(state)
            0:if(sample_valid) begin
                if(sample_in!=0) quiet_frames<=0;
                else if(quiet_frames<4096) quiet_frames<=quiet_frames+1'b1;
                // At 84ms of exact source silence the 110Hz/Q3 mode is below
                // -80dB. Clear sub-LSB fixed-point limit cycles deterministically.
                if(sample_in==0 && quiet_frames>=4095) begin
                    x<=0;x1<=0;x2<=0;dc_state<=0;dc_input<=0;sample_out<=0;valid<=1;
                    for(i=0;i<4;i=i+1) begin y1[i]<=0;y2[i]<=0;end
                end else begin
                    x<=$signed({{8{sample_in[15]}},sample_in})<<<8;dry<=sample_in;
                    dc_state<=($signed({{8{sample_in[15]}},sample_in})<<<8)-dc_input+dc_state-dc_loss;
                    dc_input<=$signed({{8{sample_in[15]}},sample_in})<<<8;
                    total<=0;mode<=0;state<=1;
                end
            end
            1:begin
                product_a<=y1[mode]*body_a1(mode);product_b<=y2[mode]*body_a2(mode);
                product_c<=delta*body_b(mode);state<=2;
            end
            2:begin
                mode_value<=rounded;state<=3;
            end
            3:begin
                y2[mode]<=y1[mode];y1[mode]<=mode_value>28'sd8388607 ? 24'sh7fffff :
                    mode_value< -28'sd8388608 ? 24'sh800000 : mode_value[23:0];
                total<=total+mode_value;
                if(mode==3) state<=4;else begin mode<=mode+1'b1;state<=1;end
            end
            4:begin
                sample_out<=pcm>28'sd32767 ? 16'sh7fff : pcm< -28'sd32768 ? 16'sh8000 : pcm[15:0];
                valid<=1;x2<=x1;x1<=x;state<=0;
            end
            default:state<=0;
        endcase
    end
endmodule
